# Path: tests/test_startup_health.py\nimport json\nfrom pathlib import Path\n\nfrom PC_ENGINE.core.recovery import RecoveryManager\nfrom PC_ENGINE.core.startup_health import StartupHealth\n\ndef test_startup_health_is_paper_safe(tmp_path: Path):\n    recovery = RecoveryManager(tmp_path / "runtime_state.json")\n    report = StartupHealth(tmp_path, {"mode": "PAPER"}).run(recovery)\n    assert report["status"] == "READY"\n    assert report["paper_only"] is True\n    assert report["real_promotion_attempted"] is False\n    assert (tmp_path / "startup_health.json").exists()\n\ndef test_real_config_is_forced_to_safe_startup(tmp_path: Path):\n    recovery = RecoveryManager(tmp_path / "runtime_state.json")\n    report = StartupHealth(tmp_path, {"mode": "REAL"}).run(recovery)\n    assert report["status"] == "SAFE_STATE"\n    assert "startup_mode" in report["critical_checks"]\n    assert report["checks"]["startup_mode"]["effective"] == "PAPER"\n\ndef test_startup_health_is_deterministic_json(tmp_path: Path):\n    recovery = RecoveryManager(tmp_path / "runtime_state.json")\n    StartupHealth(tmp_path, {"mode": "PAPER"}).run(recovery)\n    payload = json.loads((tmp_path / "startup_health.json").read_text(encoding="utf-8"))\n    assert payload["schema_version"] == 1\n    assert payload["checks"]["recovery_integrity"]["generation"] == 0